window.SEARCH_INDEX = [{"theme":"kodomo","themeName":"子どもの権利","id":"n_restore","scope":"national","category":"子の連れ去りの防止","label":"実子誘拐（正当な理由のない子の連れ去り）の防止","words":"連れ去り 子供 子ども 別居 離婚 親権","text":"正当な理由のない子の連れ去りの防止と解決\n正当な理由（DV・虐待からの避難等）のない子の連れ去りについて、原状回復を原則とし、別居直後から親子交流を迅速に確保する仕組みを整備すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_joint","scope":"national","category":"改正民法と家庭裁判所","label":"改正民法（共同親権）の運用改善と見直し","words":"共同親権 単独親権 離婚後 民法改正 親権","text":"改正民法の施行後の運用改善と見直し\n改正民法の施行状況（共同親権の選択状況、親子交流の取決め・実施状況等）を調査・公表し、子が父母双方から養育を受けられるよう、運用の改善と制度の見直しを行うこと。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_reform","scope":"national","category":"子の連れ去りの防止","label":"施行後5年の見直しで、無断の子の居所の変更を法律で禁じる（家族法の再改正）","words":"共同親権 連れ去り 引っ越し 転居 民法改正","text":"施行後の見直しにおける、正当な理由のない子の居所の変更の禁止の法定\n改正民法の附則第19条第2項に基づく施行後の見直しにおいて、DV・虐待からの避難等の正当な理由がある場合を除き、父母の一方が他方に無断で子の居所を変更することを禁じ、その場合には元の状態に戻すことを原則とし、親権者の指定・変更において考慮することを、法律に明記すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_lawyer","scope":"national","category":"離婚事件の弁護活動","label":"葛藤を高める離婚弁護活動の規制","words":"弁護士 離婚 連れ去り 指南","text":"父母の葛藤を不必要に高める弁護活動への対応\n子の連れ去りの教唆や、父母の葛藤を不必要に高める弁護活動を懲戒事由として明確化するなど、子の利益を最優先とする職務規範を整備するとともに、調停・ADR等の協調的な紛争解決を推進すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_criminal","scope":"national","category":"子の連れ去りの防止","label":"略取誘拐罪の適正な運用（親であることを理由に起訴をためらわない）","words":"連れ去り 誘拐 警察 検察 刑事","text":"親による子の連れ去りに対する未成年者略取誘拐罪の適正な運用\n親による子の連れ去りであっても未成年者略取誘拐罪が成立し得るとした最高裁判例を踏まえ、DV・虐待からの避難等の正当な理由がある場合を除き、行為者が親権者であることや家族の間の紛争であることのみを理由として、警察が被害届の受理や捜査を、検察が起訴を控えることのないよう、検察庁法第14条に基づく法務大臣の一般的な指示や警察庁の通達等により、適正な運用を確保すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_prosecution_stats","scope":"national","category":"子の連れ去りの防止","label":"親による子の連れ去り事件の捜査・起訴の件数の把握と公表","words":"連れ去り 誘拐 警察 検察 統計","text":"親による子の連れ去り事件の処理状況の把握と公表\n親による子の連れ去りが問題となった事件について、警察における相談・被害届の受理と送致、検察における起訴・不起訴（不起訴の理由の別を含む）の件数を把握して毎年公表し、判例を踏まえた適切な対応がされているかを検証すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_fee","scope":"national","category":"離婚事件の弁護活動","label":"婚姻費用・養育費を原資とする弁護士報酬の規制","words":"弁護士 成功報酬 養育費 離婚","text":"子のための給付を原資とする弁護士報酬の実態調査\n子の養育のための婚姻費用・養育費の一部を弁護士報酬に充てる報酬体系について実態を調査し、子のための給付が子以外の目的に流出しないよう必要な措置を講じること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_gov_info","scope":"national","category":"関係修復と共同養育の推進","label":"国の相談・広報における情報提供の均衡","words":"広報 内閣府 相談 共同親権","text":"国の相談・広報における情報提供の均衡\n内閣府男女共同参画局をはじめとする国の相談・広報において、DV被害者の安全確保に加え、子を連れた別居が子と他方の親との関係に及ぼす影響、改正民法における父母の協力義務、親子交流の重要性についても併せて周知すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_court","scope":"national","category":"改正民法と家庭裁判所","label":"家庭裁判所の体制強化","words":"家裁 家庭裁判所 調停 裁判官","text":"家庭裁判所の体制強化\n家庭裁判所調査官・調停委員の増員と研修の充実を図り、別居直後の親子交流や監護者指定の審理を迅速化すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_support","scope":"national","category":"養育費と経済的な支援","label":"養育費の確保とひとり親家庭の経済支援","words":"ひとり親 母子家庭 父子家庭 シングル 生活費","text":"養育費の確保とひとり親家庭の経済的自立の支援\n改正民法で導入された法定養育費制度の周知と、養育費の確実な履行を確保する仕組みを強化するとともに、ひとり親家庭の経済的自立を支援すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_feelink","scope":"national","category":"養育費と経済的な支援","label":"監護費用（養育費）の請求と親子交流の実施を結びつける","words":"面会交流 養育費 親子交流 会えない","text":"子の監護に要する費用の請求と親子交流の実施の一体的な確保\nDV・虐待など子の安全上の支障がある場合を除き、子の監護に要する費用（法定養育費を含む）について、他方の親と子との定期的な交流（写真や手紙の送付のみなどの間接的な交流を除き、直接の面会による交流に限る。）の実施の程度に応じて請求できる額が定まる仕組みとし、交流が行われていない場合は法定養育費の額（子1人あたり月額2万円）までに限り、交流が定期的かつ充実して行われるほど、家庭裁判所で用いられる算定表の額まで段階的に上がるよう、民法その他の関係法令を改正すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_advance","scope":"national","category":"養育費と経済的な支援","label":"養育費の立替払いと公的な取立ての制度","words":"養育費 不払い 未払い 立て替え 取り立て ひとり親","text":"公的機関による養育費の立替払いと取立ての制度の創設\n養育費が支払われない場合に、国が一定額を立て替えて支払い、支払義務のある親から公的に取り立てる制度を創設すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_counsel","scope":"national","category":"関係修復と共同養育の推進","label":"離婚前の関係修復支援（夫婦カウンセリング）","words":"夫婦 離婚 カウンセリング 修復 夫婦げんか","text":"離婚前の夫婦関係修復支援\nDV・虐待のない夫婦が、離婚の前に夫婦カウンセリングや関係修復支援を受けられる公的な仕組みを整備すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_voice","scope":"national","category":"改正民法と家庭裁判所","label":"子どもの意見表明の保障","words":"子どもの権利 子供の権利 意見 気持ち 子どもの声","text":"親権・監護の決定における子どもの意見表明の保障\n親権・監護・親子交流の決定にあたり、子どもの年齢と発達に応じて、その意見を聴き、尊重する手続を保障すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_childrep","scope":"national","category":"改正民法と家庭裁判所","label":"子どもの手続代理人の費用を国が負担する","words":"子どもの権利 手続代理人 弁護士 家庭裁判所","text":"家事事件における子どもの手続代理人の利用の拡大\n家事事件における子どもの手続代理人について、その報酬を国が負担する制度を設け、父母の対立が激しい事件などで積極的に選任されるよう運用を改めること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_urgent","scope":"national","category":"子の連れ去りの防止","label":"「急迫の事情」の解釈の明確化","words":"共同親権 単独 急迫 連れ去り","text":"改正民法における「急迫の事情」の解釈の明確化\n改正民法における「子の利益のため急迫の事情があるとき」の解釈について、DV・虐待からの避難が妨げられないよう配慮しつつ、その範囲を明確にし、相談機関・自治体・関係機関に周知すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_dvmeasure","scope":"national","category":"DV支援措置と一時保護","label":"DV等支援措置（住民票の閲覧制限）の国の運用基準の見直し","words":"DV 住民票 支援措置 居場所 虚偽","text":"DV等支援措置の運用基準の見直し\nDV等支援措置について、被害者保護を確保しつつ、延長時の確認、裁判所の判断など客観的な事情の変化があった場合の見直し、措置の対象とされた者が事情を説明できる手続について、国として運用の基準を示すこと。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_genderplan","scope":"national","category":"関係修復と共同養育の推進","label":"男女共同参画基本計画に共同養育を位置づける","words":"男女共同参画 共同養育 子育て","text":"男女共同参画基本計画における離婚後の共同養育の位置づけ\n男女共同参画基本計画に、父母の別居・離婚後の共同養育の推進と、性別を問わないDV被害者支援を位置づけ、DV被害者の安全確保と親子関係の維持の両立を図ること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_reunite","scope":"national","category":"関係修復と共同養育の推進","label":"低葛藤の別居家庭での同居再開の支援（円満調停の活用）","words":"別居 同居 復縁 円満調停 家族","text":"低葛藤の別居家庭における家族の同居再開に向けた支援\nDV・虐待のない低葛藤の別居家庭について、家庭裁判所や行政の相談において、子を監護する親に家族の同居再開という選択肢を示し、夫婦関係調整調停（円満）や夫婦カウンセリング等の関係修復支援につなぐ運用を整備すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"n_tempcare","scope":"national","category":"DV支援措置と一時保護","label":"児童相談所の一時保護の運用の検証と統計の公表","words":"児相 児童相談所 一時保護 虐待","text":"児童相談所の一時保護の適正な運用の検証\n虐待等から真に保護が必要な子どもを確実に守ることを前提に、2025年6月に始まった一時保護の司法審査の運用状況を検証し、一時保護の件数・期間・解除の理由、家庭復帰後の支援の状況などの統計を公表するとともに、必要に応じて運用の改善を図ること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_school","scope":"local","category":"学校・行政の手続","label":"学校行事への参加と、学校から両方の親への情報提供","words":"学校 運動会 授業参観 通知表 別居親","text":"学校・保育所における父母双方への情報提供と行事参加\n学校・保育所等において、安全上の支障がない限り、別居・離婚後も父母双方に子の学校生活や行事に関する情報を提供し、行事への参加を認めるよう、教育委員会等から通知すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_disaster","scope":"local","category":"学校・行政の手続","label":"災害時の連絡先に別居親を加える","words":"災害 地震 防災 連絡先 別居親","text":"災害時等における別居親への連絡\n学校・保育所等の緊急連絡先について、安全上の支障がない限り別居親も登録できるようにし、災害時等に子の安否を父母双方に伝える仕組みを整えること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_visit","scope":"local","category":"離婚前後の親子への支援","label":"親子交流（面会交流）の支援事業","words":"面会交流 会えない 親子交流 別居親","text":"親子交流支援事業の実施・拡充\n別居親と子の親子交流を支援する事業（交流場所の提供、付添い・受渡しの支援、費用の助成等）を実施し、父母の合意形成前の相談にも対象を広げること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_guidance","scope":"local","category":"離婚前後の親子への支援","label":"離婚前後の親向け講座と情報提供","words":"離婚 講座 親ガイダンス 共同養育","text":"離婚前後の父母への情報提供と講座の実施\n離婚届の配布・受理時や離婚相談の際に、養育計画・親子交流・養育費に関する情報と取決め書式を提供し、離婚前後の父母を対象とした講座を実施すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_dvmeasure","scope":"local","category":"DV相談と支援措置","label":"住民票の閲覧制限（DV等支援措置）の点検","words":"DV 住民票 支援措置 居場所","text":"DV等支援措置の適正な運用\n住民基本台帳事務におけるDV等支援措置について、被害者の安全を最優先としつつ、申出内容の確認を適切に行うこと。また、延長の際には支援の必要性を改めて確認し、保護命令や家庭裁判所の判断など客観的な事情の変化があったときは、措置の継続の要否を見直すこと。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_consult","scope":"local","category":"離婚前後の親子への支援","label":"相談窓口での共同養育の情報提供","words":"相談 窓口 共同養育 離婚","text":"相談窓口における情報提供の充実\n自治体の相談窓口において、安全確保の支援と併せて、子と他方の親との関係維持、親子交流、改正民法の内容についても情報提供し、別居親も相談できる体制を整えること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_dvcrime","scope":"local","category":"DV相談と支援措置","label":"DV相談で、子の連れ去りが略取誘拐罪に当たり得ることを案内する","words":"DV 連れ去り 誘拐 相談","text":"DV相談における子の連れ去りと未成年者略取誘拐罪についての情報提供\nDV・女性相談等の窓口において、DV・虐待からの避難を妨げないことを前提としつつ、正当な理由のない子の連れ去りや連れ戻しは、親権者による行為であっても未成年者略取誘拐罪（刑法第224条）に当たり得るとする最高裁判例があることを、相談者に案内すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_childcare","scope":"local","category":"離婚前後の親子への支援","label":"離婚後の子への定期的なカウンセリングと、親子関係の断絶の確認","words":"カウンセリング 子供 子ども 離婚後 心のケア","text":"父母の別居・離婚後の子どもへの定期的な相談支援\n父母の別居・離婚を経験した子どもに対し、スクールカウンセラーやこども家庭センター等を通じて定期的にカウンセリングの機会を設けるとともに、DV・虐待など安全上の支障がある場合を除き、子どもが他方の親との関係を不当に断たれていないかを確認し、必要な支援につなげること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_counsel","scope":"local","category":"夫婦関係の修復","label":"夫婦関係修復相談・カウンセリング費用の助成","words":"夫婦 カウンセリング 助成 補助 修復","text":"夫婦関係修復のための相談支援\nDV・虐待のない夫婦を対象に、夫婦関係の修復に向けた相談窓口の設置やカウンセリング費用の助成を行うこと。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_checkup","scope":"local","category":"夫婦関係の修復","label":"乳幼児健診などの機会に、夫婦関係・家庭環境の相談を案内する","words":"健診 乳幼児 夫婦 家庭","text":"乳幼児健診等の機会を活用した家庭環境の改善支援\n乳幼児健診、新生児訪問、こども家庭センターでの相談等の機会に、夫婦関係・家族関係の相談窓口やカウンセリング、父母がともに子育てに関わるための講座を案内し、DV・虐待が疑われる場合の安全確保と併せて、家庭環境の改善を支援すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_childvoice","scope":"local","category":"離婚前後の親子への支援","label":"こども基本法に基づく子どもの声の反映","words":"こども基本法 子どもの声 意見 子供","text":"父母の別居・離婚を経験した子どもの声の反映\nこども基本法の趣旨に基づき、父母の別居・離婚を経験した子どもの意見を聴き、{宛先}の施策に反映すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_transfer","scope":"local","category":"学校・行政の手続","label":"転校・転園の手続での父母双方の意思の確認","words":"転校 転園 学校 保育園 別居親","text":"転校・転園の手続における改正民法への対応\n父母がともに親権者である子の転校・転園の手続にあたっては、改正民法の趣旨を踏まえ、DV・虐待からの避難等の事情に配慮しつつ、他方の親権者の意思の確認方法を定め、学校・保育所に周知すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_genderplan","scope":"local","category":"計画と職員の研修","label":"男女共同参画計画に、離婚後も父母がともに子育てすることを位置づける","words":"男女共同参画 共同養育 子育て","text":"男女共同参画計画における離婚後の共同養育の位置づけ\n{宛先}の男女共同参画計画の改定に際し、父母の別居・離婚後も父母がともに子育てに関わること（共同養育）の推進を施策として位置づけること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_allvictims","scope":"local","category":"DV相談と支援措置","label":"性別を問わずDV被害を相談できる窓口","words":"DV 男性 相談 窓口","text":"性別を問わないDV相談体制の整備\n男性を含め、性別にかかわらずDV・モラルハラスメントの被害を相談できる窓口を設け、その存在を広く周知すること。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_training","scope":"local","category":"計画と職員の研修","label":"相談員・職員への改正民法の研修","words":"研修 職員 相談員 共同親権 民法改正","text":"相談員・職員に対する改正民法の研修\nDV・女性相談、男女共同参画、子育て支援、学校、住民窓口の相談員・職員に対し、改正民法（父母の協力義務、親権の共同行使、親子交流）について研修を行うこと。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_reunite","scope":"local","category":"夫婦関係の修復","label":"低葛藤の別居家庭への同居再開の案内","words":"別居 同居 復縁 家族","text":"低葛藤の別居家庭に対する家族の同居再開に向けた案内と支援\nDV・虐待のない低葛藤の別居家庭について、子を監護する親が手続や相談に訪れた際に、家族の同居再開という選択肢と、夫婦関係調整調停（円満）や夫婦カウンセリング等の関係修復支援の情報を提供し、希望する場合は支援につなぐこと。"},{"theme":"kodomo","themeName":"子どもの権利","id":"l_advance","scope":"local","category":"離婚前後の親子への支援","label":"養育費の立替払いの実施","words":"養育費 不払い 未払い 立て替え ひとり親","text":"養育費の立替払いと取立ての支援の実施\n{宛先}において、取り決められた養育費が支払われないひとり親家庭に対し、立替払いや支払義務のある親への督促、強制執行の手続費用の支援を行うこと。"},{"theme":"dansei","themeName":"男女平等","id":"n_neutral","scope":"national","category":"制度の男女差の見直し","label":"性別で対象を限った支援の検証（女性に限った優遇の見直し）","words":"男女平等 女性優遇 逆差別 女性限定","text":"性別により対象を限定した支援施策の検証と見直し\n国の支援施策のうち性別により対象を限定しているものについて、その必要性と効果を検証し、性別にかかわらず困難を抱える人が必要な支援を受けられるよう見直すこと。"},{"theme":"dansei","themeName":"男女平等","id":"n_dv_men","scope":"national","category":"男性への支援","label":"男性のDV被害者を保護する体制の整備","words":"DV 男性 被害 シェルター 夫","text":"男性のDV被害者の相談・一時保護体制の整備\n男性のDV被害者が性別にかかわらず相談と一時保護を受けられるよう、国として体制を整備し、都道府県が男性の避難先を確保するための財政措置を講じること。"},{"theme":"dansei","themeName":"男女平等","id":"n_suicide","scope":"national","category":"男性への支援","label":"男性の自殺対策の強化","words":"自殺 男性 自死 こころ","text":"男性の自殺対策の強化\n男性の自殺者数が女性の約2倍で推移している実態を踏まえ、その要因を分析し、男性が利用しやすい相談体制の整備など、男性に届く自殺対策・孤独孤立対策を重点的に推進すること。"},{"theme":"dansei","themeName":"男女平等","id":"n_social","scope":"national","category":"制度の男女差の見直し","label":"社会保障制度に残る男女差の点検","words":"遺族年金 寡婦 社会保障 年金 男女差","text":"社会保障制度に残る男女差の点検と解消\n遺族厚生年金の男女差を解消する見直しを円滑に施行するとともに、年金・手当等の社会保障制度に残る性別による取扱いの差を点検し、その解消を図ること。"},{"theme":"dansei","themeName":"男女平等","id":"n_dv_bias","scope":"national","category":"DV施策の見直し","label":"DV施策での「加害者は男性、被害者は女性」という思い込みの点検","words":"DV 男性 被害者 偏見","text":"DV施策における性別の思い込みの点検\n国のDVに関する施策・啓発資料・相談員等の研修について、「加害者は男性、被害者は女性」という性別による思い込みがないかを点検し、性別にかかわらず被害者が相談・保護を受けられる内容に改めること。"},{"theme":"dansei","themeName":"男女平等","id":"n_dv_preamble","scope":"national","category":"DV施策の見直し","label":"DV防止法の前文の「被害者は、多くの場合女性」という記述の見直し","words":"DV防止法 配偶者暴力防止法 前文 男性","text":"配偶者暴力防止法の前文の見直し\n配偶者からの暴力の防止及び被害者の保護等に関する法律の前文にある「配偶者からの暴力の被害者は、多くの場合女性であり」とする記述を見直し、性別にかかわらず被害者を保護するという法の趣旨に沿う表現に改めること。"},{"theme":"dansei","themeName":"男女平等","id":"n_rousai","scope":"national","category":"男性への支援","label":"仕事で亡くなる人の9割超が男性である実態を踏まえた労働安全対策","words":"労災 労働災害 過労死 職場 事故 男性","text":"男性に偏る死亡災害を踏まえた労働安全対策の強化\n死亡災害の9割超を男性が占めている実態を踏まえ、労働災害の男女別の分析を公表するとともに、男性が多く従事する業種における死亡災害の防止対策を強化し、男女共同参画基本計画においても課題として位置づけること。"},{"theme":"dansei","themeName":"男女平等","id":"n_joshiwaku","scope":"national","category":"制度の男女差の見直し","label":"大学入試の「女子枠」の撤廃","words":"女子枠 大学 入試 逆差別 理工系","text":"大学入学者選抜における女子枠の撤廃\n大学入学者選抜実施要項から「理工系分野における女子等」を例示する記述を削除するなど、性別により出願資格を限定する選抜（いわゆる女子枠）を促す施策を見直し、大学入学者選抜が性別にかかわらず同じ条件で行われるよう、女子枠の撤廃を図ること。"},{"theme":"dansei","themeName":"男女平等","id":"n_ratio","scope":"national","category":"制度の男女差の見直し","label":"法令と補助金で男女の比率や「女子枠」を求める仕組みの見直し","words":"女子枠 女性比率 補助金 クオータ 逆差別","text":"補助金等の配分や法令において性別の比率や女子枠を求める仕組みの見直し\n補助金・交付金・助成金の配分や審査において、性別により対象を限定した選抜枠（いわゆる女子枠）を設けることや特定の性別の比率を高めることを評価の対象や交付の要件とする仕組みを廃止し、あわせて、法令において性別の比率を数値目標として求める規定について、性別による差別的取扱いを生まないよう検証し、見直すこと。"},{"theme":"dansei","themeName":"男女平等","id":"l_consult","scope":"local","category":"男性への相談と支援","label":"男性向けの相談窓口の設置","words":"男性 相談 窓口 悩み","text":"男性のための相談窓口の設置\n{宛先}において、家庭・仕事・DV被害・孤立などの悩みを男性が相談できる窓口を設け、夜間や電話・オンラインなど利用しやすい形で実施するとともに、その周知を図ること。"},{"theme":"dansei","themeName":"男女平等","id":"l_shelter","scope":"local","category":"男性への相談と支援","label":"男性のDV被害者の避難先の確保","words":"DV 男性 シェルター 避難","text":"男性のDV被害者が避難できる場所の確保\n{宛先}において、男性のDV被害者が安全に避難できるよう、宿泊施設や民間団体への委託等により一時的な避難先を確保し、相談窓口から確実につなぐ体制を整えること。"},{"theme":"dansei","themeName":"男女平等","id":"l_review","scope":"local","category":"事業と計画の見直し","label":"女性に限った事業の点検（性別を問わない支援へ）","words":"女性限定 女性優遇 逆差別 事業","text":"性別により対象を限定した事業の点検\n{宛先}の事業のうち、性別により対象を限定しているものを点検してその理由と効果を公表し、必要に応じて性別にかかわらず利用できる形に改めること。"},{"theme":"dansei","themeName":"男女平等","id":"l_plan","scope":"local","category":"事業と計画の見直し","label":"男女共同参画計画に男性の困難を位置づける","words":"男女共同参画 男性","text":"男女共同参画計画への男性の困難の位置づけ\n{宛先}の男女共同参画計画の策定・見直しにあたり、男性の孤立・自殺・DV被害などの実態を調査し、男性が抱える困難への具体的な取り組みと目標を位置づけること。"},{"theme":"dansei","themeName":"男女平等","id":"l_dv_bias","scope":"local","category":"事業と計画の見直し","label":"DVの啓発・相談での「加害者は男性、被害者は女性」という思い込みの点検","words":"DV 男性 被害者 偏見 啓発","text":"DVの啓発・相談における性別の思い込みの点検\n{宛先}のDVに関する啓発資料・相談窓口の案内・職員および相談員の研修について、「加害者は男性、被害者は女性」という性別による思い込みがないかを点検し、性別にかかわらず被害者が相談しやすく、適切に対応される内容に改めること。"},{"theme":"dansei","themeName":"男女平等","id":"l_dv_men_forms","scope":"local","category":"男性への相談と支援","label":"男性が受けるDVの形（暴言・監視・無視など）の周知と、それに合わせた相談","words":"DV モラハラ 精神的暴力 男性 夫","text":"男性が受ける配偶者からの暴力の形を示した周知と、それに合わせた相談の体制\n{宛先}のDVに関する啓発資料と相談窓口の案内において、暴言、交友関係や行動の監視・制限、長期間の無視、生活費を渡さないなど、男性が配偶者等から受けることの多い心理的・経済的な暴力の具体的な例を示して、男性も被害者になりうることを周知するとともに、男性の相談員による相談や電話・メールでの相談など、男性が相談しやすい体制を整えること。"},{"theme":"dansei","themeName":"男女平等","id":"l_dv_intake","scope":"local","category":"事業と計画の見直し","label":"DV相談の多角的な聴取と支援案内","words":"DV 相談 聞き取り","text":"男女共同参画の相談窓口におけるDV相談の多角的な運用\n{宛先}の男女共同参画に関する相談窓口において、DVの相談を一律にDVと認定したり、シェルター等を機械的に案内したりするのではなく、安全上の危険を適切に評価したうえで、相談者の同意に基づく夫婦カウンセリング等の選択肢の案内や、必要に応じた双方からの事情聴取など、多角的な運用を行うこと。"},{"theme":"dansei","themeName":"男女平等","id":"l_suicide","scope":"local","category":"男性への相談と支援","label":"自殺対策計画に男性への取り組みを位置づける","words":"自殺 男性 自死 こころ","text":"地域自殺対策計画における男性への取り組みの位置づけ\n{宛先}の自殺対策計画の策定・見直しにあたり、地域の男性の自殺の実態を分析し、離婚・別居後の孤立を含め、男性が抱える困難に届く相談体制や早期に気づく取り組みを、目標とともに位置づけること。"},{"theme":"dansei","themeName":"男女平等","id":"l_shed","scope":"local","category":"男性への相談と支援","label":"男性が集まれる地域の居場所（メンズシェッド等）への支援","words":"居場所 孤独 孤立 男性 高齢","text":"男性が孤立しないための地域の居場所づくりへの支援\n{宛先}の孤独・孤立対策および自殺対策において、男性が作業や役割を通じて交流できる地域の居場所（メンズシェッド等）の立ち上げと運営を、公共施設の提供や情報発信などにより支援すること。"},{"theme":"dansei","themeName":"男女平等","id":"l_sexviolence","scope":"local","category":"男性への相談と支援","label":"男性・男児の性暴力被害者も相談・支援の対象として明記する","words":"性暴力 性被害 男性 男の子","text":"男性・男児の性暴力被害者への相談・支援の明確化\n{宛先}の性犯罪・性暴力に関する相談窓口と啓発の案内において、男性・男児の被害者も相談・支援の対象であることを明記し、男性の被害者を適切な支援につなぐ手順を整えること。"},{"theme":"dansei","themeName":"男女平等","id":"l_father","scope":"local","category":"男性への相談と支援","label":"父親を子育て支援の対象に（両親学級の休日開催・父親の産後うつ対策）","words":"父親 パパ 育児 産後うつ 両親学級","text":"父親を対象とした子育て支援の充実\n{宛先}の子育て支援において、両親学級の休日・夜間の開催や、乳幼児健診・訪問の機会に父親の心身の不調に気づき相談につなぐ取り組みなど、父親を支援の対象として位置づけること。"},{"theme":"dansei","themeName":"男女平等","id":"l_council","scope":"local","category":"事業と計画の見直し","label":"審議会の委員を「男女どちらも40%以上」にする","words":"審議会 委員 男女比 クオータ","text":"審議会等委員の男女比の目標の見直し\n{宛先}の審議会等の委員について、国の第6次男女共同参画基本計画にならい、男女いずれの委員も40%を下回らないことを目標とし、審議会ごとの男女の割合を公表すること。"},{"theme":"dansei","themeName":"男女平等","id":"l_homeless","scope":"local","category":"男性への相談と支援","label":"路上生活・生活困窮の支援で、男性に届く訪問と相談を","words":"ホームレス 生活困窮 路上生活 男性","text":"路上生活者・生活困窮者への支援における男性への取り組み\n{宛先}の路上生活者・生活困窮者への支援において、支援を必要とする人の多くが男性である実態を踏まえ、巡回による声かけや、仕事・住まい・健康をまとめて相談できる場を設けるなど、男性に届く形で支援を行うこと。"},{"theme":"dansei","themeName":"男女平等","id":"l_joshiwaku","scope":"local","category":"事業と計画の見直し","label":"公立大学の入試で「女子枠」を設けない","words":"女子枠 公立大学 入試 逆差別","text":"公立大学の入学者選抜における女子枠の撤廃\n{宛先}が設置する公立大学（公立大学法人が設置するものを含む）の入学者選抜において、性別により出願資格を限定する選抜（いわゆる女子枠）を設けず、既に設けている場合は撤廃するよう求めること。"},{"theme":"dansei","themeName":"男女平等","id":"l_ratio","scope":"local","category":"事業と計画の見直し","label":"市の補助金・入札で「女子枠」や女性の比率を条件や加点にしない","words":"女子枠 女性比率 補助金 入札 加点","text":"補助金等の交付や入札において性別の比率や女子枠を条件としないこと\n{宛先}の補助金・助成金の交付や入札・プロポーザルの評価の基準を点検し、性別により対象を限定した枠（いわゆる女子枠）を設けることや、特定の性別の比率の高さを交付の条件や加点の対象とすることをやめ、性別にかかわらず公平に評価される仕組みとすること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_welfare","scope":"national","category":"社会保障","label":"外国人への生活保護の見直し（廃止を含めて）","words":"外国人 生活保護 永住者","text":"外国人に対する生活保護の措置の見直し\n外国人に対する生活保護を法律によらない行政措置として行う現在の運用について、廃止を含めてその在り方を見直し、対象と要件を法律で明確に定めること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_insurance","scope":"national","category":"社会保障","label":"外国人の保険料未納・医療費不払いへの対策","words":"外国人 国民健康保険 医療費 未払い 未納","text":"外国人の社会保険料未納と医療費不払いへの対策の着実な実施\n保険料を滞納する外国人の在留審査への反映など、外国人の社会保険料の未納対策を予定どおり確実に実施するとともに、医療費の不払いを防ぐ対策を強化し、そのための自治体の体制整備を支援すること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_foreign_birth","scope":"national","category":"社会保障","label":"外国人への出産育児一時金の廃止","words":"外国人 出産育児一時金 出産","text":"外国人に対する出産育児一時金の廃止\n外国人に対する出産育児一時金の支給を廃止し、出産に関する公的給付の対象と要件を、国籍・在留資格・滞在期間との関係を含めて法律で明確に定めること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_land","scope":"national","category":"土地と安全保障","label":"安全保障上重要な土地の取得規制の強化","words":"土地 外国資本 外資 安全保障 基地","text":"安全保障上重要な土地の取得に対する規制の強化\n重要土地等調査法を改正し、安全保障上重要な施設の周辺や水源地等の土地の取得について、事前の審査や許可制の導入を含む実効性のある規制を早期に整備すること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_overstay","scope":"national","category":"入国・在留と治安","label":"不法滞在・不法就労の対策の推進","words":"不法滞在 不法就労 オーバーステイ 入管","text":"不法滞在・不法就労の対策の着実な推進\n「不法滞在者ゼロプラン」に基づく対策を着実に推進し、不法就労を助長する雇用主への対応を含め、不法滞在・不法就労の防止の実効性を高めること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_entry_screening","scope":"national","category":"入国・在留と治安","label":"犯罪歴のある外国人の入国を防ぐ審査の強化","words":"入国 入管 犯罪 審査 ビザ","text":"犯罪歴のある外国人の入国を防ぐ審査の強化\n電子渡航認証制度の早期導入と、外国の当局との犯罪歴の情報の共有の推進により、上陸拒否の対象となる犯罪歴のある外国人の入国を確実に防ぐこと。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_welfare_residence","scope":"national","category":"社会保障","label":"生活保護を申請する外国人の在留の見直し（帰国を含めて）","words":"外国人 生活保護 在留 ビザ","text":"生活保護を申請する外国人の在留の在り方の見直し\n生活保護を申請した外国人について、在留資格の更新・変更の審査に反映させ、本国への帰国の支援や退去強制を含めて、在留の在り方を見直すこと。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_deport_criminals","scope":"national","category":"入国・在留と治安","label":"罪を犯した外国人の退去強制の徹底","words":"外国人 犯罪 強制送還 退去","text":"罪を犯した外国人の退去強制の徹底\n罪を犯して退去強制の対象となった外国人について、改正入管法を確実に運用して速やかに送還するとともに、送還の受入れを拒む国への働きかけを強化すること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_foreign_crime_prosecution","scope":"national","category":"入国・在留と治安","label":"通訳を要する事件の勾留期間の延長と捜査体制の強化","words":"外国人 犯罪 通訳 警察","text":"通訳を要する事件の勾留期間の延長と捜査体制の強化\n被疑者が日本語を解さず通訳を要する事件について、刑事訴訟法を改正して起訴前の勾留の延長ができる期間を長くするとともに、通訳人の確保や国際捜査共助の迅速化などの捜査体制を強化し、処分保留で釈放された外国人の所在の把握と出国の管理を徹底し、適正な起訴の判断ができるようにすること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_trainee_employer","scope":"national","category":"入国・在留と治安","label":"技能実習生の管理を受入れ企業に強く求める","words":"技能実習 実習生 失踪 外国人労働者","text":"技能実習生・育成就労外国人の受入れ企業による管理の徹底\n技能実習制度・育成就労制度において、受入れ企業に、適正な労働条件の確保と、受け入れた外国人の所在と就労の状況の把握を強く求め、失踪や不法就労を防げなかった企業には受入れの停止を含む厳しい措置を取ること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_candidate_nationality","scope":"national","category":"国籍と公職・通称","label":"立候補する人の国籍（帰化の経歴を含む）の公表","words":"選挙 候補者 国籍 帰化","text":"国会議員と地方議員の選挙に立候補する者の国籍に関する情報の公表\n国会議員及び地方議会議員の選挙に立候補する者に、外国の国籍の有無並びに帰化による日本の国籍の取得の有無及び従前の国籍を届け出させ、選挙公報等により有権者に公表する制度を設けること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_civil_service_nationality","scope":"national","category":"国籍と公職・通称","label":"公務員の上級職・管理職を日本国籍の人に限ることの法定","words":"公務員 国籍 管理職 国籍条項","text":"公権力の行使や政策の決定に関わる公務員を日本国籍を有する者に限ることの法律による明確化\n公権力の行使又は重要な政策の決定に関わる国家公務員及び地方公務員の上級の職・管理職には、日本の国籍を有する者のみが就くことができることを、法律で明確に定めること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"n_tsusho","scope":"national","category":"国籍と公職・通称","label":"外国人住民の通称（通名）を使える範囲の縮小","words":"通名 通称 外国人 住民票","text":"外国人住民の通称の記載の要件の厳格化と利用範囲の縮小\n外国人住民の住民票への通称の記載の要件を厳格にし、通称の記載のし直しを制限するとともに、公的な証明書や本人確認の場面では本名の記載を基本とするなど、通称の利用範囲を縮小すること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"l_welfare","scope":"local","category":null,"label":"外国人への生活保護の状況の公表","words":"外国人 生活保護 公表","text":"外国人に対する生活保護の実施状況の公表\n{宛先}が行政措置として実施している外国人に対する生活保護について、受給世帯数・人員・国籍別の内訳・支給総額等を毎年度公表すること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"l_insurance","scope":"local","category":null,"label":"外国人の国民健康保険料の徴収の強化","words":"外国人 国民健康保険 国保 未納","text":"外国人の国民健康保険料の納付状況の把握と徴収の強化\n{宛先}の国民健康保険について、外国人の加入者の納付状況を把握して公表するとともに、加入時の説明、転出・出国前の納付確認、国の在留審査との情報連携への対応など、保険料の徴収を強化すること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"l_land","scope":"local","category":null,"label":"水源地・重要な土地の取引の把握","words":"水源 土地 外国資本 外資 森林","text":"水源地等の重要な土地の取引の把握\n{宛先}において、水源地や重要な施設の周辺など住民の生活と安全に関わる土地について、事前の届出を求める条例の制定を含め、取引と所有の状況を把握する仕組みを整えること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"l_rules","scope":"local","category":null,"label":"外国人住民への生活ルールの周知と指導","words":"外国人 ごみ 騒音 マナー 生活ルール","text":"外国人住民への地域の生活ルールの周知と指導の徹底\n{宛先}において、外国人住民の転入手続の際に、ごみの出し方・騒音・駐車など地域の生活ルールを多言語で分かりやすく伝えるとともに、ルールが守られない場合に自治体が指導を行う体制を整えること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"l_school_culture","scope":"local","category":null,"label":"学校の食文化・伝統行事を守る（宗教食は持参で対応）","words":"給食 ハラール 宗教 学校","text":"学校給食と学校行事における日本の食文化・伝統文化の尊重\n{宛先}の学校給食と学校行事において、宗教・文化上の理由による個別の事情には家庭からの弁当の持参などで対応することを基本とし、そのことを理由に給食の献立、「いただきます」「ごちそうさま」のあいさつ、伝統行事など日本の食文化・学校文化を取りやめないこと。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"l_civil_service_nationality","scope":"local","category":null,"label":"自治体の管理職を日本国籍の人に限る","words":"公務員 国籍 管理職 国籍条項","text":"公権力の行使や政策の決定に関わる管理職への任用を日本国籍を有する者に限ること\n{宛先}の職員のうち、公権力の行使又は重要な政策の決定に関わる管理職への任用は、日本の国籍を有する者に限ることを、任用の基準として明確に定めること。"},{"theme":"nihonjin","themeName":"日本人の権利","id":"l_tsusho","scope":"local","category":null,"label":"外国人住民の通称（通名）の記載の審査の厳格化","words":"通名 通称 外国人 住民票","text":"外国人住民の通称の記載の審査の厳格化\n{宛先}において、外国人住民の住民票への通称の記載の申出に対し、その呼称が社会生活上通用していることを示す資料を厳格に確認し、記載と削除を繰り返す申出には慎重に対応すること。"},{"theme":"shiho","themeName":"司法への参加","id":"n_family_open","scope":"national","category":null,"label":"家庭裁判所の審理の取材と、匿名にした公開","words":"家裁 家庭裁判所 公開 取材 裁判","text":"家庭裁判所の手続の透明化\n家庭裁判所の家事事件の手続について、子と当事者を匿名にすることを条件に、報道機関等による審理の傍聴と報道を認める仕組みや、審判書を匿名にして公表する仕組みを、諸外国の例も踏まえて検討し、必要な法整備を行うこと。"},{"theme":"shiho","themeName":"司法への参加","id":"n_family_stats","scope":"national","category":null,"label":"家庭裁判所の判断の結果を、詳しい統計で公表","words":"家裁 家庭裁判所 統計 親権","text":"家庭裁判所の家事事件の結果に関する詳しい統計の公表\n家庭裁判所の家事事件について、親権者・監護者の指定の結果（父母の別、共同親権・単独親権の別を含む）、面会交流の頻度と方法、子の引渡しの認容率、審理の期間などの詳しい統計を毎年公表するよう、政府が裁判所と協議し、必要な措置を講じること。"},{"theme":"shiho","themeName":"司法への参加","id":"n_appointment","scope":"national","category":null,"label":"最高裁判所の裁判官の選び方の公開","words":"最高裁 裁判官 任命 人事","text":"最高裁判所の裁判官の選考の過程の透明化\n最高裁判所の裁判官の任命について、選考の基準と過程、任命の理由を国民に公表するとともに、外部の有識者が意見を述べる諮問の仕組みを設けることを検討すること。"},{"theme":"shiho","themeName":"司法への参加","id":"n_review","scope":"national","category":null,"label":"国民審査の判断材料の充実と、制度の見直し","words":"最高裁 裁判官 国民審査 選挙","text":"最高裁判所裁判官の国民審査の実効性の向上\n最高裁判所裁判官の国民審査について、審査公報等で裁判官ごとの関与した判決と個別意見を詳しく示して判断の材料を充実させるとともに、信任・不信任を明確に示せる投票の方法の導入を含め、国民の意思が正しく反映される制度への見直しを検討すること。"},{"theme":"shiho","themeName":"司法への参加","id":"n_lay","scope":"national","category":null,"label":"家事・行政の裁判への国民の参加の拡大","words":"裁判員 国民参加 家事 行政訴訟","text":"家事事件・行政事件などの裁判への国民の参加の拡大\n裁判員制度の対象を家事事件や行政事件などに広げることや、家事事件の参与員の活用と選任の状況の公表など、刑事事件以外の裁判にも国民の感覚が反映される仕組みを検討すること。"},{"theme":"shiho","themeName":"司法への参加","id":"n_complaint","scope":"national","category":null,"label":"裁判所の運営への意見・苦情を受ける第三者の窓口","words":"裁判所 苦情 意見 第三者","text":"裁判所の手続の運営に関する意見・苦情を受け付ける第三者機関の設置\n裁判の結論ではなく、手続の運営や当事者への対応について国民の意見・苦情を受け付ける、裁判所から独立した第三者の仕組みを設け、受け付けた件数と対応の状況を毎年公表することを検討すること。"},{"theme":"shiho","themeName":"司法への参加","id":"n_mediator","scope":"national","category":null,"label":"家事調停委員の選び方と研修の公開","words":"調停委員 家裁 家庭裁判所 調停","text":"家事調停委員の選任と研修の透明化\n家事調停委員の選任の基準と過程、任命後の研修の内容を国民に公表するとともに、調停を利用した当事者へのアンケートを行ってその結果を公表し、運営の改善に生かすよう、政府が裁判所と協議し、必要な措置を講じること。"},{"theme":"shiho","themeName":"司法への参加","id":"l_review_info","scope":"local","category":null,"label":"国民審査の判断材料を住民に届ける","words":"国民審査 最高裁 裁判官 選挙","text":"最高裁判所裁判官の国民審査に関する情報の住民への周知\n{宛先}の選挙管理委員会において、最高裁判所裁判官の国民審査の際に、審査公報とあわせて、裁判官ごとの関与した判決を調べられる公的な情報の案内を、選挙の広報紙やホームページで住民に分かりやすく周知すること。"},{"theme":"shiho","themeName":"司法への参加","id":"l_school","scope":"local","category":null,"label":"学校で、司法と国民審査を学ぶ機会を増やす","words":"学校 教育 主権者教育 裁判 国民審査","text":"学校教育における司法と国民審査についての学習の充実\n{宛先}の学校教育において、主権者教育の一環として、最高裁判所裁判官の国民審査や裁判員制度など、国民が司法に関わる仕組みについて学ぶ機会を充実させること。"},{"theme":"kenko","themeName":"国民の健康","id":"n_tobacco","scope":"national","category":"たばこ・お酒・砂糖","label":"たばこ税の引上げ（WHOの勧める水準へ）","words":"タバコ 喫煙 たばこ税 禁煙 増税","text":"国民の健康を守るためのたばこ税の引上げ\nWHOが勧める水準（小売価格に占める税の割合が少なくとも75％）を目指して、国民の健康を守る観点からたばこ税を段階的に引き上げ、その税収を禁煙の支援や医療の財源に充てることを検討すること。"},{"theme":"kenko","themeName":"国民の健康","id":"n_alcohol","scope":"national","category":"たばこ・お酒・砂糖","label":"酒税の見直し（健康を守る観点から）","words":"お酒 酒 飲酒 酒税 増税","text":"国民の健康を守る観点からの酒税の見直し\n国民の健康を守る観点から、WHOの勧告を踏まえ、アルコールの量に応じた課税や物価の上昇に合わせた定期的な見直しを含め、酒税の水準の引上げを検討し、その税収を飲酒による健康の害を防ぐ施策に充てること。"},{"theme":"kenko","themeName":"国民の健康","id":"n_alcohol_label","scope":"national","category":"たばこ・お酒・砂糖","label":"酒類の容器への純アルコール量と飲酒量の目安の表示の義務付け","words":"お酒 酒 飲酒 アルコール 表示","text":"酒類の容器への純アルコール量と健康に配慮した飲酒量の目安の表示の義務付け\nすべての酒類の容器に、その酒類に含まれる純アルコール量（グラム）と、健康日本21（第三次）の「生活習慣病のリスクを高める量」（1日当たりの純アルコール摂取量が男性40g以上、女性20g以上）などの健康に配慮した飲酒量の目安を、見やすく表示することを法令で義務付けること。"},{"theme":"kenko","themeName":"国民の健康","id":"n_sugar","scope":"national","category":"たばこ・お酒・砂糖","label":"砂糖税（砂糖の多い食品・飲料への課税）の導入","words":"砂糖 甘い 清涼飲料 ジュース 肥満 糖尿病","text":"国民の健康を守るための砂糖の多い食品と飲料への課税の導入\n国民、特に子供の肥満と生活習慣病を防ぐため、諸外国の例も踏まえ、清涼飲料に限らず、菓子や加工食品を含む食品全体を対象に、砂糖などの糖分の量に応じて課税できる仕組みの導入を検討し、その税収を健康づくりの施策に充てること。"},{"theme":"kenko","themeName":"国民の健康","id":"n_pachinko","scope":"national","category":"ギャンブル依存","label":"パチンコ店の依存症対策の強化（本人・家族の申告による入店制限の義務付けなど）","words":"パチンコ ギャンブル 依存症 パチスロ","text":"ぱちんこ屋におけるギャンブル等依存症対策の強化\nぱちんこ屋におけるギャンブル等依存症対策として、本人・家族の申告による入店制限の仕組みをすべての店舗に義務付け、店内と広告での周知を徹底すること、射幸心をあおる広告・宣伝を制限すること、店舗の内外での現金の引出しや貸付けを容易にする設備を置かないことを含め、法令による規制の強化を検討すること。"},{"theme":"kenko","themeName":"国民の健康","id":"l_cancer_screening","scope":"local","category":"検診と健診","label":"がん検診と精密検査の受診率の向上","words":"がん 癌 検診 健康診断","text":"がん検診と精密検査の受診率の向上\n{宛先}において、がん検診の対象者一人一人への個別の受診勧奨と未受診者への再勧奨を行い、精密検査が必要とされた人には精密検査を受けたかを確かめて受診を勧めるとともに、検診ごとの受診率と精密検査受診率を毎年度公表すること。"},{"theme":"kenko","themeName":"国民の健康","id":"l_tokutei","scope":"local","category":"検診と健診","label":"国民健康保険の特定健診・特定保健指導の実施率の向上","words":"健診 健康診断 メタボ 国保 国民健康保険","text":"国民健康保険の特定健康診査・特定保健指導の実施率の向上\n{宛先}の国民健康保険において、特定健康診査を受けやすいよう、休日や夜間の実施、がん検診との同時の実施、身近な医療機関での個別の実施などを広げるとともに、受けていない人への個別の勧奨を強め、特定健康診査と特定保健指導の実施率を毎年度公表すること。"},{"theme":"kenko","themeName":"国民の健康","id":"l_smoke_free","scope":"local","category":"たばこ・お酒・砂糖","label":"子供の集まる場所での受動喫煙の防止","words":"タバコ 喫煙 受動喫煙 副流煙 公園 通学路","text":"子供が利用する場所とその周辺での受動喫煙の防止\n{宛先}において、通学路、公園、学校・保育所等の出入口の周辺など、子供が日常的に利用する屋外の場所での受動喫煙を防ぐため、実態を調べたうえで、喫煙を控える区域の指定や表示、周知などの措置を講ずること。"},{"theme":"kenko","themeName":"国民の健康","id":"l_gamble","scope":"local","category":"ギャンブル依存","label":"ギャンブル依存症の相談窓口と、パチンコ店の入店制限の周知","words":"パチンコ ギャンブル 依存症 相談","text":"ギャンブル等依存症の相談支援の充実と、ぱちんこ屋の入店制限の仕組みの周知\n{宛先}において、ギャンブル等依存症の相談窓口と、本人・家族の申告によるぱちんこ屋等への入店制限の仕組みを、広報紙やホームページ、地域のぱちんこ屋等と連携した掲示などで周知するとともに、借金や家族の問題も含めて相談できるよう、保健、消費生活、福祉の窓口の連携を強めること。都道府県にあっては、ギャンブル等依存症対策推進計画にこれらの取組を位置付けること。"},{"theme":"sonota","themeName":"その他","id":"n_school_tax","scope":"national","category":null,"label":"学校法人への課税の見直し","words":"私立学校 学校法人 非課税 税金","text":"学校法人に対する課税の在り方の見直し\n学校法人に対する法人税と固定資産税の非課税・軽減税率の措置について、教育の用に直接供しない資産や、教育と関わりの薄い事業から生じる所得に適正に課税されるよう、課税の範囲と税率の在り方を見直すこと。"},{"theme":"sonota","themeName":"その他","id":"n_religion_tax","scope":"national","category":null,"label":"宗教法人への課税の見直し","words":"宗教法人 お寺 寺 神社 教会 非課税 税金","text":"宗教法人に対する課税の在り方の見直し\n信教の自由を尊重しつつ、宗教法人に対する法人税と固定資産税の非課税・軽減税率の措置について、収益を生む事業や、宗教の本来の用に供しない資産に、一般の事業者と公平に課税されるよう、課税の範囲と税率の在り方を見直すこと。"},{"theme":"sonota","themeName":"その他","id":"n_private_free","scope":"national","category":null,"label":"私立高校の授業料無償化（私立への上乗せ）の撤廃","words":"高校無償化 私立高校 授業料 無償化","text":"私立高等学校等の授業料への上乗せ支援の撤廃と、公立高等学校の維持\n高等学校等就学支援金のうち、私立高等学校等の生徒に対する、公立高等学校の授業料相当額（年11万8800円）を超える上乗せの支援を撤廃し、その財源を、地域の公立高等学校の維持と教育の充実に充てること。"},{"theme":"sonota","themeName":"その他","id":"n_npo","scope":"national","category":null,"label":"NPO法人の会計報告の厳格化","words":"NPO 会計 不正 補助金","text":"特定非営利活動法人（NPO法人）の会計報告の厳格化\n特定非営利活動法人について、一定の規模以上の法人や、国・自治体から多額の委託費・補助金を受ける法人に公認会計士又は監査法人による外部の監査を義務付けること、計算書類の様式と会計の基準を統一し、所轄庁が提出された事業報告書等を点検して誰もがインターネットで閲覧できるようにすること、事業報告書等を提出しない法人への措置を強めることを含め、会計報告の仕組みを厳格にするよう、特定非営利活動促進法を改正すること。"},{"theme":"sonota","themeName":"その他","id":"l_public_school","scope":"local","category":null,"label":"公立高校の統廃合の前に、影響を調べて公表する","words":"公立高校 統廃合 学校 廃校","text":"公立高等学校の維持と、統廃合の前の影響の調査・公表\n{宛先}において、公立高等学校の統廃合や募集の停止を検討する際は、通学の時間と費用、地域の生徒が進学できる学校の選択肢への影響をあらかじめ調査して住民に公表するとともに、地域で学べる公立高等学校の維持に努めること。"},{"theme":"sonota","themeName":"その他","id":"l_npo_open","scope":"local","category":null,"label":"委託・補助を受けるNPO法人などの会計の公開","words":"NPO 会計 公開 委託 補助金","text":"委託費・補助金を受ける団体の会計の公開\n{宛先}において、NPO法人その他の団体に支出した委託費・補助金について、団体名、事業の内容、金額と、使い道の報告（実績報告）を、毎年度ホームページで公表するとともに、一定額以上の支出について使い道の点検を強めること。"},{"theme":"sonota","themeName":"その他","id":"l_book_display","scope":"local","category":null,"label":"性的な描写のある本（ボーイズラブ作品を含む）を児童書と分けて置かせる","words":"図書館 本屋 書店 BL 本 ゾーニング","text":"性的な描写のある図書類の区分陳列の徹底\n{宛先}において、書店等で性的な描写を含む図書類が児童書の近くに置かれたり、平積みで子供の目に触れたりすることのないよう、ボーイズラブ作品を含め分野にかかわらず同じ基準で、青少年の健全な育成に関する条例に基づく区分陳列の実態を調査し、書店等への指導を強めること。また、市区町村にあっては、都道府県と連携して実態を調べ、都道府県に指導の強化を求めること。"}];
